import{_ as a,o as t,c as s,ag as i}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Caching, Distributed Cache, Redis Cluster, and Consistent Hashing","description":"","frontmatter":{},"headers":[],"relativePath":"system_design/caching/CachingAndDistributedCache.md","filePath":"system_design/caching/CachingAndDistributedCache.md"}'),o={name:"system_design/caching/CachingAndDistributedCache.md"};function r(n,e,c,h,d,l){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="caching-distributed-cache-redis-cluster-and-consistent-hashing" tabindex="-1">Caching, Distributed Cache, Redis Cluster, and Consistent Hashing <a class="header-anchor" href="#caching-distributed-cache-redis-cluster-and-consistent-hashing" aria-label="Permalink to &quot;Caching, Distributed Cache, Redis Cluster, and Consistent Hashing&quot;">​</a></h1><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><h3 id="why-caching-exists" tabindex="-1">Why caching exists <a class="header-anchor" href="#why-caching-exists" aria-label="Permalink to &quot;Why caching exists&quot;">​</a></h3><p>Repeatedly fetching the same data from a database is expensive. With a cache between the application and the database, frequently accessed data is served from memory instead of disk-backed storage — significantly reducing latency and database load.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User → Application → Cache → Database</span></span></code></pre></div><h3 id="cache-hit-vs-cache-miss" tabindex="-1">Cache hit vs cache miss <a class="header-anchor" href="#cache-hit-vs-cache-miss" aria-label="Permalink to &quot;Cache hit vs cache miss&quot;">​</a></h3><ul><li><strong>Hit:</strong> requested data exists in cache — the database is never touched.</li><li><strong>Miss:</strong> data is absent → fetch from DB → store in cache → return. Future requests become hits.</li></ul><h3 id="cache-invalidation" tabindex="-1">Cache invalidation <a class="header-anchor" href="#cache-invalidation" aria-label="Permalink to &quot;Cache invalidation&quot;">​</a></h3><p>The hardest problem in caching is keeping cache and database synchronized. If the DB says <code>name = John</code> but the cache still says <code>name = Swapnil</code>, users see stale data. Common approaches after a DB write:</p><ul><li><strong>Delete the cache entry</strong> (<code>UPDATE DB</code> + <code>DEL cache_key</code>) — next read repopulates the cache.</li><li><strong>Update the cache entry</strong> (<code>UPDATE DB</code> + <code>UPDATE CACHE</code>) — both stay synchronized.</li></ul><h3 id="cache-states" tabindex="-1">Cache states <a class="header-anchor" href="#cache-states" aria-label="Permalink to &quot;Cache states&quot;">​</a></h3><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Cold</strong></td><td>Little/no useful data — hit rate ≈ 0% (e.g. right after a Redis restart); most requests hit the DB</td></tr><tr><td><strong>Warm</strong></td><td>Some frequently used data present — moderate hit rate</td></tr><tr><td><strong>Hot</strong></td><td>Most requests served from cache — high hit rate, optimal performance</td></tr></tbody></table><h2 id="cache-read-patterns" tabindex="-1">Cache read patterns <a class="header-anchor" href="#cache-read-patterns" aria-label="Permalink to &quot;Cache read patterns&quot;">​</a></h2><h3 id="cache-aside-lazy-loading" tabindex="-1">Cache-aside (lazy loading) <a class="header-anchor" href="#cache-aside-lazy-loading" aria-label="Permalink to &quot;Cache-aside (lazy loading)&quot;">​</a></h3><p>The most common production pattern. The <strong>application</strong> manages both cache and DB:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Read → check cache → hit? return</span></span>
<span class="line"><span>                   → miss → read DB → store in cache → return</span></span></code></pre></div><h3 id="read-through" tabindex="-1">Read-through <a class="header-anchor" href="#read-through" aria-label="Permalink to &quot;Read-through&quot;">​</a></h3><p>The application talks <strong>only to the cache</strong>; on a miss the <em>cache itself</em> fetches from the DB.</p><table tabindex="0"><thead><tr><th>Cache-aside</th><th>Read-through</th></tr></thead><tbody><tr><td>Application manages cache population</td><td>Cache manages cache population</td></tr><tr><td>App talks to cache and DB</td><td>App talks only to cache</td></tr></tbody></table><h2 id="cache-write-patterns" tabindex="-1">Cache write patterns <a class="header-anchor" href="#cache-write-patterns" aria-label="Permalink to &quot;Cache write patterns&quot;">​</a></h2><h3 id="write-through" tabindex="-1">Write-through <a class="header-anchor" href="#write-through" aria-label="Permalink to &quot;Write-through&quot;">​</a></h3><p>Writes go to cache and database <strong>synchronously</strong>: write → cache → DB → success. Strong consistency, slower writes, cache always fresh. Good when consistency matters.</p><h3 id="write-around" tabindex="-1">Write-around <a class="header-anchor" href="#write-around" aria-label="Permalink to &quot;Write-around&quot;">​</a></h3><p>Writes <strong>bypass the cache</strong> and go straight to the DB; the cache is populated later during reads (read-after-write is a miss). Useful for many-writes/few-reads workloads — avoids wasting cache space.</p><h3 id="write-back-write-behind" tabindex="-1">Write-back (write-behind) <a class="header-anchor" href="#write-back-write-behind" aria-label="Permalink to &quot;Write-back (write-behind)&quot;">​</a></h3><p>Writes go to <strong>cache first</strong>, success returns immediately, and the database is updated asynchronously later. Very low write latency, eventual consistency, <strong>risk of data loss if the cache crashes before the DB sync</strong>.</p><p>Important detail: <strong>Redis does not magically update the database</strong> — a background worker, queue consumer, or application process performs the eventual DB write.</p><h2 id="cache-eviction" tabindex="-1">Cache eviction <a class="header-anchor" href="#cache-eviction" aria-label="Permalink to &quot;Cache eviction&quot;">​</a></h2><p>When the cache is full, entries must be removed. <strong>LRU (Least Recently Used)</strong> — removes entries not accessed recently — is the most important policy for interviews. FIFO and others exist but are far less commonly discussed; understanding LRU well is usually sufficient.</p><h2 id="cache-layers" tabindex="-1">Cache layers <a class="header-anchor" href="#cache-layers" aria-label="Permalink to &quot;Cache layers&quot;">​</a></h2><h3 id="cpu-style-intuition" tabindex="-1">CPU-style intuition <a class="header-anchor" href="#cpu-style-intuition" aria-label="Permalink to &quot;CPU-style intuition&quot;">​</a></h3><p>L1/L2/L3 caches come from CPU architecture. General principle: <strong>closer = faster = smaller; farther = slower = larger.</strong> System design borrows the same idea:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Application memory → Redis → Database</span></span></code></pre></div><p>Each layer trades speed for capacity.</p><h3 id="multi-level-caching" tabindex="-1">Multi-level caching <a class="header-anchor" href="#multi-level-caching" aria-label="Permalink to &quot;Multi-level caching&quot;">​</a></h3><p>Multiple layers are common because each solves a different problem:</p><ul><li><strong>Local (in-process) cache</strong> — extremely fast, no network hop, lives inside the app process.</li><li><strong>Redis</strong> — shared across instances, larger capacity.</li></ul><h2 id="local-vs-global-vs-distributed-cache" tabindex="-1">Local vs global vs distributed cache <a class="header-anchor" href="#local-vs-global-vs-distributed-cache" aria-label="Permalink to &quot;Local vs global vs distributed cache&quot;">​</a></h2><h3 id="local-cache" tabindex="-1">Local cache <a class="header-anchor" href="#local-cache" aria-label="Permalink to &quot;Local cache&quot;">​</a></h3><p>Each app server maintains its own cache. Fastest possible access (no network hop), but <strong>invalidation becomes difficult</strong> — when data changes, every server&#39;s copy is stale and all must be updated.</p><h3 id="global-cache" tabindex="-1">Global cache <a class="header-anchor" href="#global-cache" aria-label="Permalink to &quot;Global cache&quot;">​</a></h3><p>A single logical cache stores all data — <strong>no sharding</strong>. It can absolutely have replicas and failover:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Applications → Redis primary → replicas</span></span></code></pre></div><p>Key correction: global cache does NOT mean &quot;no failover.&quot; The defining property is <strong>no data partitioning</strong>. With a 100 GB primary and two 100 GB replicas, useful capacity is still 100 GB — replicas hold duplicates.</p><h3 id="distributed-cache" tabindex="-1">Distributed cache <a class="header-anchor" href="#distributed-cache" aria-label="Permalink to &quot;Distributed cache&quot;">​</a></h3><p>Data is <strong>partitioned</strong> across nodes — each stores different keys (Node A → user set 1, B → set 2, C → set 3). Effective capacity is the sum: three 100 GB nodes = <strong>300 GB useful cache</strong>.</p><h2 id="redis-cluster-architecture" tabindex="-1">Redis Cluster architecture <a class="header-anchor" href="#redis-cluster-architecture" aria-label="Permalink to &quot;Redis Cluster architecture&quot;">​</a></h2><p>Common production deployment — sharding + replication + automatic failover:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Master A → Replica A</span></span>
<span class="line"><span>Master B → Replica B</span></span>
<span class="line"><span>Master C → Replica C</span></span></code></pre></div><p>If Master B dies, Replica B is promoted and the cluster continues operating. (Cluster mechanics — heartbeats, leader election — in <code>system_design/clustering/Clustering.md</code>.)</p><p><strong>Important clarification:</strong> a distributed cache is not fault tolerant merely because multiple nodes exist. If Node A dies, B and C do NOT automatically have A&#39;s data — without replication, A&#39;s data is gone. <strong>Multiple nodes provide scaling; replication provides fault tolerance.</strong></p><h3 id="redis-sharding-—-hash-slots" tabindex="-1">Redis sharding — hash slots <a class="header-anchor" href="#redis-sharding-—-hash-slots" aria-label="Permalink to &quot;Redis sharding — hash slots&quot;">​</a></h3><p>Redis Cluster uses <strong>16384 hash slots</strong>. Every key maps to a slot; slots are assigned to nodes:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>user:1 → slot 250      Node A → slots 0–5000</span></span>
<span class="line"><span>user:2 → slot 7000     Node B → slots 5001–10000</span></span>
<span class="line"><span>user:3 → slot 12000    Node C → slots 10001–16383</span></span></code></pre></div><h2 id="consistent-hashing" tabindex="-1">Consistent hashing <a class="header-anchor" href="#consistent-hashing" aria-label="Permalink to &quot;Consistent hashing&quot;">​</a></h2><h3 id="the-problem-with-modulo-hashing" tabindex="-1">The problem with modulo hashing <a class="header-anchor" href="#the-problem-with-modulo-hashing" aria-label="Permalink to &quot;The problem with modulo hashing&quot;">​</a></h3><p>Naive: <code>hash(key) % N</code>. With 3 nodes → <code>% 3</code>; add a fourth → <code>% 4</code> — <strong>most keys remap to different nodes</strong>, causing massive cache misses and a nearly cold cache.</p><h3 id="core-idea-—-the-hash-ring" tabindex="-1">Core idea — the hash ring <a class="header-anchor" href="#core-idea-—-the-hash-ring" aria-label="Permalink to &quot;Core idea — the hash ring&quot;">​</a></h3><p>Nodes are placed on a hash ring; keys are mapped onto the same ring. A key belongs to the <strong>first node encountered clockwise</strong>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A ---- B ---- C ---- D          (add E)</span></span>
<span class="line"><span>A ---- B ---- E ---- C ---- D</span></span></code></pre></div><p>Only keys in E&#39;s newly acquired range move; everything else is untouched. E.g. if Node C owned range 40–70, after adding E: 40–55 → E, 55–70 → C — only that slice moves.</p><h3 id="how-much-data-moves" tabindex="-1">How much data moves? <a class="header-anchor" href="#how-much-data-moves" aria-label="Permalink to &quot;How much data moves?&quot;">​</a></h3><p>Adding a node to an N-node cluster moves roughly the share the new node should own:</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th><th>Approx keys moved</th></tr></thead><tbody><tr><td>4 nodes</td><td>5 nodes</td><td>~20%</td></tr><tr><td>10 nodes</td><td>11 nodes</td><td>~9%</td></tr><tr><td>100 nodes</td><td>101 nodes</td><td>~1%</td></tr></tbody></table><p>Compare with modulo hashing: almost everything moves.</p><h3 id="virtual-nodes-vnodes" tabindex="-1">Virtual nodes (vnodes) <a class="header-anchor" href="#virtual-nodes-vnodes" aria-label="Permalink to &quot;Virtual nodes (vnodes)&quot;">​</a></h3><p>Real systems don&#39;t place one position per server — each physical node appears <strong>multiple times</strong> on the ring (<code>A1 A2 A3 A4</code>, <code>B1 B2 B3 B4</code>, ...). Benefits: better load balancing, more even distribution, and a new node steals small amounts from <em>many</em> nodes instead of one large chunk from a single neighbor.</p><h2 id="gotchas-trick-questions" tabindex="-1">Gotchas / Trick questions <a class="header-anchor" href="#gotchas-trick-questions" aria-label="Permalink to &quot;Gotchas / Trick questions&quot;">​</a></h2><ol><li><strong>&quot;Multiple cache nodes means fault tolerance.&quot;</strong> Incorrect — if A dies, B and C don&#39;t automatically have A&#39;s data. <strong>Replication provides fault tolerance; sharding provides scaling.</strong></li><li><strong>&quot;Global cache means no failover.&quot;</strong> Incorrect — a global cache can have primary + replicas with failover. The actual distinction: global = no sharding; distributed = sharding.</li><li><strong>&quot;Redis updates the database in write-behind.&quot;</strong> Incorrect — Redis stores the write; a background worker or application process eventually updates the DB.</li><li><strong>&quot;Consistent hashing means no keys move.&quot;</strong> Incorrect — keys still move, but only the keys needed by the new node, instead of nearly all keys.</li><li><strong>&quot;Going 4 → 5 nodes shifts every node&#39;s data.&quot;</strong> True for modulo hashing / repartitioning a line — NOT consistent hashing, which changes ownership only for ranges affected by the inserted node.</li><li><strong>&quot;Distributed cache nodes all contain some of the same data.&quot;</strong> Not by default — each node owns its keys; shared copies exist only when replication is configured.</li></ol><h2 id="performance-characteristics" tabindex="-1">Performance characteristics <a class="header-anchor" href="#performance-characteristics" aria-label="Permalink to &quot;Performance characteristics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Approach</th><th>Read speed</th><th>Write speed</th><th>Consistency</th><th>Risk</th></tr></thead><tbody><tr><td>Cache-aside</td><td>Fast after warm-up</td><td>Fast</td><td>Medium</td><td>Stale cache</td></tr><tr><td>Read-through</td><td>Fast</td><td>Fast</td><td>Medium</td><td>Stale cache</td></tr><tr><td>Write-through</td><td>Very fast reads</td><td>Slower writes</td><td>High</td><td>Low</td></tr><tr><td>Write-around</td><td>Slower reads after writes</td><td>Fast writes</td><td>High</td><td>Cache misses</td></tr><tr><td>Write-back</td><td>Fast reads</td><td>Fastest writes</td><td>Eventual</td><td>Data loss if cache fails</td></tr></tbody></table><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><p>Multiple cache layers (local cache → Redis → database) exist because each solves a different latency/capacity problem — mirroring the CPU&#39;s L1 → L2 → L3 hierarchy where closer layers are faster but smaller.</p><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. Cache-aside vs read-through?</strong> A. Cache-aside is managed by the application; read-through is managed by the cache layer.</p><p><strong>Q. Most common caching pattern in production?</strong> A. Cache-aside with Redis.</p><p><strong>Q. Biggest risk of write-back caching?</strong> A. The cache may fail before the asynchronous DB synchronization completes.</p><p><strong>Q. Sharding vs replication?</strong> A. Sharding increases capacity; replication increases availability.</p><p><strong>Q. Global cache vs distributed cache?</strong> A. Global stores all data on one logical node (no partitioning); distributed partitions data across nodes.</p><p><strong>Q. Why is modulo hashing problematic?</strong> A. Adding/removing nodes remaps most keys → massive cache misses.</p><p><strong>Q. Why does consistent hashing help?</strong> A. Only the subset of keys needed by the new node remaps instead of nearly all keys.</p>`,81)])])}const g=a(o,[["render",r]]);export{u as __pageData,g as default};
